<?php
defined('ABSPATH') || exit;

class GHBC_WPCLI extends WP_CLI_Command {

    /**
     * Import code chunks from a JSON file generated by scripts/extract_pdf.py
     *
     * ## OPTIONS
     *
     * <file>
     * : Path to the JSON file (e.g., code-chunks.json)
     *
     * [--dry-run]
     * : Show what would be imported without inserting
     *
     * ## EXAMPLES
     *
     *     wp ghbc import code-chunks.json
     *     wp ghbc import code-chunks.json --dry-run
     */
    public function import($args, $assoc) {
        $file = $args[0];
        if (!file_exists($file)) {
            WP_CLI::error("File not found: $file");
        }

        $data = json_decode(file_get_contents($file), true);
        if (empty($data['chunks'])) {
            WP_CLI::error('No chunks found in JSON file');
        }

        $chunks = $data['chunks'];
        $dry_run = !empty($assoc['dry-run']);
        $total = count($chunks);
        $imported = 0;
        $skipped = 0;

        WP_CLI::line("Source: {$data['source']}");
        WP_CLI::line("Total chunks in file: $total");
        if ($dry_run) {
            WP_CLI::warning('DRY RUN — no data will be inserted');
        }

        // Check if FULLTEXT index exists
        global $wpdb;
        $indexes = $wpdb->get_results("SHOW INDEX FROM {$wpdb->posts} WHERE Key_name = 'ghbc_fulltext'");
        if (empty($indexes)) {
            WP_CLI::warning('FULLTEXT index not found on wp_posts. Run: wp ghbc setup-db');
        }

        $progress = WP_CLI\Utils\make_progress_bar("Importing $total chunks", $total);

        foreach ($chunks as $chunk) {
            // Skip tiny chunks
            if (empty($chunk['content']) || strlen($chunk['content']) < 30) {
                $skipped++;
                $progress->tick();
                continue;
            }

            // Check for duplicates by clause reference
            $clause = $chunk['clause'] ?? '';
            $section = $chunk['section'] ?? '';
            $title = $chunk['title'] ?? '';
            $type = $chunk['type'] ?? 'text';

            $exists = false;
            if ($clause) {
                $exists = $wpdb->get_var($wpdb->prepare(
                    "SELECT ID FROM {$wpdb->posts} p
                     INNER JOIN {$wpdb->postmeta} m ON p.ID = m.post_id
                     WHERE p.post_type = 'ghbc_chunk'
                       AND m.meta_key = '_ghbc_clause'
                       AND m.meta_value = %s
                     LIMIT 1",
                    $clause
                ));
            }

            if ($exists) {
                $skipped++;
                $progress->tick();
                continue;
            }

            if ($dry_run) {
                $imported++;
                $progress->tick();
                continue;
            }

            $content = $chunk['content'];
            // Strip markdown headers we added during extraction
            $content = preg_replace('/^#+\s/', '', $content);

            $post_id = wp_insert_post([
                'post_type'    => 'ghbc_chunk',
                'post_status'  => 'publish',
                'post_title'   => mb_substr($title, 0, 200),
                'post_content' => wp_kses_post($content),
                'post_name'    => sanitize_title($title),
            ]);

            if (is_wp_error($post_id)) {
                WP_CLI::warning("Failed to insert: {$chunk['title']}");
                $progress->tick();
                continue;
            }

            update_post_meta($post_id, '_ghbc_part', (int)($chunk['part'] ?? 0));
            update_post_meta($post_id, '_ghbc_section', $section);
            update_post_meta($post_id, '_ghbc_clause', $clause);
            update_post_meta($post_id, '_ghbc_chunk_type', $type);

            if (!empty($chunk['page_start'])) {
                update_post_meta($post_id, '_ghbc_page_start', (int)$chunk['page_start']);
                update_post_meta($post_id, '_ghbc_page_end', (int)($chunk['page_end'] ?? $chunk['page_start']));
            }

            $imported++;
            $progress->tick();
        }

        $progress->finish();

        WP_CLI::success("Imported: $imported, Skipped (duplicates/tiny): $skipped, Total: $total");
    }

    /**
     * Set up database tables and FULLTEXT indexes.
     */
    public function setup_db() {
        global $wpdb;

        // Create queries log table
        $table = $wpdb->prefix . 'ghbc_queries';
        $charset = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE IF NOT EXISTS $table (
            id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
            user_id bigint(20) unsigned NOT NULL,
            query text NOT NULL,
            response longtext,
            tokens_used int(11) DEFAULT 0,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY user_id (user_id)
        ) $charset;";

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        dbDelta($sql);

        // Add FULLTEXT index on wp_posts for ghbc_chunk search
        $indexes = $wpdb->get_results("SHOW INDEX FROM {$wpdb->posts} WHERE Key_name = 'ghbc_fulltext'");
        if (empty($indexes)) {
            $wpdb->query("ALTER TABLE {$wpdb->posts} ADD FULLTEXT INDEX ghbc_fulltext (post_title, post_content)");
            WP_CLI::success('FULLTEXT index created on wp_posts (post_title, post_content)');
        } else {
            WP_CLI::line('FULLTEXT index already exists');
        }

        // Count existing chunks
        $count = wp_count_posts('ghbc_chunk')->publish ?? 0;
        WP_CLI::line("Existing code chunks: $count");
    }

    /**
     * Show stats about imported code chunks.
     */
    public function stats() {
        global $wpdb;

        $total = wp_count_posts('ghbc_chunk')->publish ?? 0;
        WP_CLI::line("Total chunks: $total");

        $parts = $wpdb->get_col("SELECT DISTINCT meta_value FROM {$wpdb->postmeta} WHERE meta_key = '_ghbc_part' ORDER BY meta_value");
        if ($parts) {
            $min = min($parts);
            $max = max($parts);
            WP_CLI::line("Parts covered: $min–$max");
        }

        $types = $wpdb->get_results("SELECT meta_value, COUNT(*) as cnt FROM {$wpdb->postmeta} WHERE meta_key = '_ghbc_chunk_type' GROUP BY meta_value");
        foreach ($types as $t) {
            WP_CLI::line("  {$t->meta_value}: {$t->cnt}");
        }

        $query_count = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ghbc_queries");
        WP_CLI::line("Total queries logged: " . (int)$query_count);
    }
}
